    correctKey: 'B',
    explanation: '室指数は室の平面形と高さの関係を表す指標で、間口と奥行の積を、作業面から光源までの高さに間口と奥行の和を掛けたもので割って求める。天井が低く平面が広い室ほど室指数は大きくなり、壁面で吸収される光の割合が減るため照明率は大きくなる。照明率は室内表面の反射率にも左右され、天井や壁が明るいほど高くなる。グレアは視野内の高輝度部分による不快感で、光源が直接見える直接グレアと、机上面やディスプレイに映り込む反射グレアがある。タスク・アンビエント照明は全般照明を抑えて作業面だけを重点的に照らす方式で、省エネルギーに寄与する。\n\n【図解】照明率を左右する要因\n要因｜照明率への影響\n室指数が大きい｜大きくなる\n室内表面の反射率が高い｜大きくなる\n器具の効率が高い｜大きくなる\n・室指数＝間口×奥行÷｛高さ×（間口＋奥行）｝',
