    explanation: '自由空間における点音源からの音は球面状に広がるため、距離の二乗に反比例して強さが小さくなる。音圧レベルでは距離が2倍になるごとに約6デシベル減衰する。\n式：減衰量＝20×log10（距離の比）\n代入：距離の比＝12÷3＝4、減衰量＝20×log10 4＝20×0.602\n計算：減衰量＝約12デシベル\n答え：音圧レベル＝80−12＝約68デシベル\nこれに対し、道路交通騒音のような線音源では音は円筒状に広がるため、距離が2倍になるごとの減衰は約3デシベルにとどまる。面音源では音源に近い範囲でほとんど減衰しない。屋外騒音の予測では、音源の種類に応じた減衰式を選ぶことが重要である。\n\n【図解】音源の種類と距離減衰\n音源の種類｜距離2倍あたりの減衰\n点音源｜約6デシベル\n線音源｜約3デシベル\n面音源｜近距離ではほぼ減衰しない\n・減衰量＝20×log10（距離の比）',
