    correctKey: 'A',
    explanation: '集合住宅の遮音性能は、空気音についてはD値、床衝撃音についてはL値で表される。D値は隣室との音圧レベル差で数値が大きいほど良く、L値は下階での床衝撃音レベルで数値が小さいほど良い。両者は大小の向きが逆であることに注意する。床衝撃音は二種類あり、軽量床衝撃音はスプーンの落下や靴音などの高音域の音で、カーペットや二重床など表面仕上げ材の緩衝性で効果的に低減できる。重量床衝撃音は子供の飛び跳ねなどによる低音域の音で、仕上げ材では低減できず、スラブを厚くしたり支持スパンを小さくして躯体の剛性と質量を高める必要がある。\n\n【図解】遮音性能の指標\n指標｜対象｜良好な方向\nD値｜室間の空気音｜数値が大きいほど良い\nL値｜床衝撃音｜数値が小さいほど良い\n・重量床衝撃音は躯体の厚さと剛性で対処する',
