    explanation: 'ホテルの計画では、宿泊部門、宴会部門、飲食部門、管理部門、設備部門のバランスと、動線の分離が要点となる。客用動線、従業員のサービス動線、物品の搬入搬出動線は明確に分離し、リネンや厨房の配膳、廃棄物の搬送が客の目に触れないようにする。客室部門の面積比率は、宴会場や飲食施設を多くもつシティホテルで40パーセントから60パーセント程度、付帯施設の少ないビジネスホテルで70パーセントから80パーセント程度となる。客室の基準階では、シングル、ツイン、スイートなどの構成比を需要に応じて設定し、水回りを積み重ねて配管を集約する。\n\n【図解】ホテルの客室部門面積比率\n種別｜客室部門の比率\nシティホテル｜40から60パーセント\nビジネスホテル｜70から80パーセント\nリゾートホテル｜40から60パーセント\n・客用動線とサービス動線は明確に分離する',
