    correctKey: 'D',
    explanation: '衛生器具の所要数は、建物用途、在館者数、男女比、利用の時間的集中度から算定する。事務所ビルでは在館者が終日分散するのに対し、劇場や競技場では幕間や休憩時間に利用が集中するため、同じ人数でも多くの器具が必要となる。女性用便所は1回当たりの使用時間が長いため、男性用より器具数を多めに設定し、待ち行列を解消する配慮が求められる。多機能便房は車椅子使用者やオストメイト、乳幼児連れなど特別な配慮を要する利用者のための設備であり、一般の便房の所要数を代替するものではない点に注意する。\n\n【図解】衛生器具算定の考慮要素\n要素｜内容\n在館者数と男女比｜基本となる算定条件\n利用の集中度｜劇場等はピークが鋭い\n使用時間の差｜女性用は多めに設定\n・多機能便房は一般便房の代替にはならない',
