    correctKey: 'C',
    explanation: '容積率は法52条1項により、延べ面積の敷地面積に対する割合と定義される。\n式：容積率＝延べ面積÷敷地面積×100\n代入：容積率＝540÷300×100\n答え：容積率＝180パーセント\n容積率の限度は、都市計画で定められた指定容積率と、前面道路の幅員による制限のうち、小さいほうの値となる。前面道路の幅員が12メートル未満の場合、住居系の用途地域では前面道路の幅員に10分の4を、その他の用途地域では10分の6を乗じた値が制限値となる。前面道路が2以上ある場合は、最大の幅員を用いて計算する。この二つの値を比較して厳しいほうを適用する手順が容積率計算の基本となる。\n\n【図解】容積率の限度の決め方\n手順｜内容\n1｜都市計画で定められた指定容積率を確認\n2｜前面道路幅員による制限値を計算\n3｜二つのうち小さいほうを適用\n・根拠は法52条1項と2項',
    difficulty: 'basic',
