    explanation: '法52条9項と令135条の18による特定道路の緩和は、幅員15メートル以上の特定道路から70メートル以内にあり、かつ前面道路の幅員が6メートル以上12メートル未満である敷地について、前面道路の幅員に一定の数値を加えたものを前面道路幅員とみなす制度である。加える数値は、12メートルから前面道路の幅員を引いた値に、70メートルから特定道路までの距離を引いた値を掛け、70で割って求める。したがって特定道路に近いほど加算値が大きく、70メートルの地点でゼロとなる。前面道路が広いほど加算値は小さくなる。\n\n【図解】特定道路緩和の要件\n項目｜要件｜根拠\n特定道路の幅員｜15メートル以上｜法52条9項\n特定道路までの距離｜70メートル以内｜法52条9項\n前面道路の幅員｜6メートル以上12メートル未満｜法52条9項\n・加算値は距離が長いほど小さくなる',
