    question: '準工業地域内で建蔽率の限度が10分の6と定められた敷地面積300平方メートルの敷地がある。この敷地が防火地域内にあり、かつ特定行政庁が指定する角地である場合、耐火建築物を建築するときの建築面積の最高限度として正しいものは、次のうちどれか。',
