    explanation: '法53条3項により、防火地域内にある耐火建築物等については10分の1、特定行政庁が指定する角地については10分の1をそれぞれ建蔽率の限度に加算でき、両方に該当する場合は合わせて10分の2を加算する。\n式1：緩和後の建蔽率＝指定建蔽率＋10分の1＋10分の1\n代入1：緩和後の建蔽率＝10分の6＋10分の2＝10分の8＝0.8\n式2：建築面積の最高限度＝敷地面積×緩和後の建蔽率\n代入2：建築面積の最高限度＝300×0.8\n答え：建築面積の最高限度＝240平方メートル\nなお指定建蔽率が10分の8の地域で防火地域内の耐火建築物等とする場合は、法53条6項1号により制限自体が適用されず、建蔽率の上限がなくなる点と区別する。\n\n【図解】建蔽率緩和の計算手順\n手順｜内容｜値\n指定建蔽率｜都市計画による｜10分の6\n防火地域の耐火建築物等｜加算｜10分の1\n特定行政庁指定の角地｜加算｜10分の1\n・合計10分の8、建築面積の限度240平方メートル',
