    explanation: '法28条1項により、住宅、学校、病院、診療所、寄宿舎、下宿その他これらに類する建築物で政令で定めるものの居室には、採光のための窓その他の開口部を設け、その採光に有効な部分の面積を居室の床面積に対して政令で定める割合以上としなければならない。事務所や店舗の居室は対象外であり、採光規定は適用されない。割合は令19条3項により、幼稚園、小学校、中学校等の教室が5分の1、住宅の居住のための居室、病院や診療所の病室、寄宿舎の寝室等が7分の1、その他の一定の居室が10分の1などと定められている。住宅の居室は照明設備等の措置により10分の1まで緩和できる。\n\n【図解】採光に必要な開口部の割合\n居室｜割合｜根拠\n幼稚園、小中学校等の教室｜5分の1｜令19条3項\n住宅の居室、病室、寝室｜7分の1｜令19条3項\n・事務所や店舗の居室には採光規定の適用がない',
