    explanation: '2階建ての1階の柱についてのN値は、1階の当該柱の両側の軸組の壁倍率の差に係数を乗じた値と、2階の対応する柱の両側の軸組の壁倍率の差に係数を乗じた値を加え、鉛直荷重による押さえの効果を表す数値を減じて求める。\n式：N＝1階の壁倍率の差×係数＋2階の壁倍率の差×係数−鉛直荷重による数値\n代入：N＝2.5×0.8＋1.5×0.8−1.0\n計算：N＝2.0＋1.2−1.0\n答え：N＝2.2\n2階建ての1階の柱では、上階の耐力壁から伝わる引抜き力も加わるため、平屋建てより大きなN値となりやすい。一方、鉛直荷重による押さえの効果を表す数値も、2階建ての1階の出隅柱では1.0、その他の柱では0.6と大きく設定されている。\n\n【図解】N値法の計算（2階建ての1階）\n項目｜計算｜値\n1階の寄与｜2.5×0.8｜2.0\n2階の寄与｜1.5×0.8｜1.2\n鉛直荷重による低減｜−1.0｜−1.0\n・N値は2.2となる',
    difficulty: 'advanced',
