    explanation: '法44条1項により、建築物又は敷地を造成するための擁壁は、道路内に、又は道路に突き出して建築し、又は築造してはならない。例外として、地盤面下に設ける建築物、公衆便所や巡査派出所等で特定行政庁が建築審査会の同意を得て許可したもの、地区計画に基づく一定の建築物、公共用歩廊等で特定行政庁が許可したものがある。法42条2項により道路とみなされた部分、すなわち中心線から2メートルの範囲は道路として扱われるため、建築物はもとより門や塀を築造することもできない。この部分は敷地面積にも算入されないため、建蔽率と容積率の計算上も不利になる。\n\n【図解】道路内に建築できる例外\n例外｜内容｜根拠\n地盤面下の建築物｜地下街等｜法44条1項1号\n公益上必要な建築物｜特定行政庁の許可｜法44条1項2号\n公共用歩廊等｜特定行政庁の許可｜法44条1項4号\n・2項道路のみなし部分には門や塀も築造できない',
