    explanation: '道路斜線制限による高さの限度は、前面道路の反対側の境界線から当該部分までの水平距離に勾配を乗じて求める。\n式：高さの限度＝反対側の境界線からの水平距離×勾配\n代入：高さの限度＝6×1.25\n答え：高さの限度＝7.5メートル\n道路境界線上の点は、道路の反対側の境界線から道路の幅員に等しい6メートルの位置にあるため、水平距離は6メートルとなる。第一種住居地域は住居系用途地域であるから勾配は1.25である。建築物を道路境界線から後退させれば、法56条2項により後退距離だけ起点が外側に移動するため、同じ位置での高さの限度が大きくなる。\n\n【図解】道路斜線の計算\n記号｜意味｜本問の値\n水平距離｜道路反対側境界線から検討点まで｜6メートル\n勾配｜住居系用途地域｜1.25\n高さの限度｜水平距離×勾配｜7.5メートル\n・道路境界線上の水平距離は道路幅員に等しい',
    difficulty: 'standard',
