    explanation: '建築士法4条により、一級建築士の免許は国土交通大臣が与え、二級建築士及び木造建築士の免許は都道府県知事が与える。免許は建築士名簿に登録することによって行われ、一級建築士については中央指定登録機関、二級建築士と木造建築士については都道府県指定登録機関が事務を行う場合がある。建築士事務所は、他人の求めに応じ報酬を得て設計等の業務を行おうとする場合に都道府県知事の登録を受けなければならず、その有効期間は5年である。更新の登録を受けなければ期間の満了により効力を失う。建築士は3年以内ごとに定期講習を受講する義務がある。\n\n【図解】免許と登録の主体\n区分｜免許又は登録の主体｜根拠\n一級建築士｜国土交通大臣｜建築士法4条1項\n二級建築士、木造建築士｜都道府県知事｜建築士法4条3項\n建築士事務所｜都道府県知事｜建築士法23条1項\n・建築士事務所の登録の有効期間は5年',
